import{_ as a,o,c as l,a2 as r}from"./chunks/framework.CHeM0PsO.js";const q=JSON.parse('{"title":"写好 PPT 的元原则：写给写 PPT 写到忘记怎么讲故事的自己","description":"","frontmatter":{},"headers":[],"relativePath":"写好PPT的元原则：写给写PPT写到忘记怎么讲故事的自己.md","filePath":"写好PPT的元原则：写给写PPT写到忘记怎么讲故事的自己.md","lastUpdated":1786770226000}'),i={name:"写好PPT的元原则：写给写PPT写到忘记怎么讲故事的自己.md"};function e(n,t,s,h,p,u){return o(),l("div",null,[...t[0]||(t[0]=[r('<h1 id="写好-ppt-的元原则-写给写-ppt-写到忘记怎么讲故事的自己" tabindex="-1">写好 PPT 的元原则：写给写 PPT 写到忘记怎么讲故事的自己 <a class="header-anchor" href="#写好-ppt-的元原则-写给写-ppt-写到忘记怎么讲故事的自己" aria-label="Permalink to &quot;写好 PPT 的元原则：写给写 PPT 写到忘记怎么讲故事的自己&quot;">​</a></h1><blockquote><p>2026-08-05 · 思考随笔 · Nathan Ma</p><p>写 PPT 写到烦躁时，人会自动退化成素材堆砌机。这篇文章是写给那个状态下的自己的恢复手册。</p></blockquote><hr><h2 id="问题的根源-你为什么会忘" tabindex="-1">问题的根源：你为什么会忘？ <a class="header-anchor" href="#问题的根源-你为什么会忘" aria-label="Permalink to &quot;问题的根源：你为什么会忘？&quot;">​</a></h2><p>写 PPT 有一个诡异的陷阱：<strong>做得越深入，越容易忘记汇报的逻辑。</strong></p><p>原因很简单。当你花了三天时间研究一个技术方案、整理一组数据、画一张架构图，你的大脑里全是细节。此时你打开 PPT，本能反应是——把我研究出来的东西全放上去。</p><p>然后你就开始堆素材。标题越来越大，bullet point 越来越多，一页塞五张图，生怕漏了什么。</p><p>但汇报对象不是你。他们没有花三天研究你的东西。他们只有 15 分钟，而且可能是在你前面三个人讲完之后、快下班之前、脑子已经不太转的时候看你的 PPT。</p><p><strong>你脑子里是网状的思考，但 PPT 只能是线性的讲述。</strong> 从网状到线性的转换，就是写 PPT 最难的地方。而当你累了、烦了，大脑会本能地逃避这个转换工作，直接往页面上倒素材。</p><p>这就是为什么你需要一套元原则——不是具体怎么排版、怎么配色，而是在你迷失细节之前，帮你重新建立汇报视角的思维框架。</p><hr><h2 id="第一条-总分总-不是说说的" tabindex="-1">第一条：总分总，不是说说的 <a class="header-anchor" href="#第一条-总分总-不是说说的" aria-label="Permalink to &quot;第一条：总分总，不是说说的&quot;">​</a></h2><p>&quot;总分总&quot;是每个人都知道的 PPT 原则。但知道和做到之间，差的是一次认真的自我检查。</p><h3 id="什么叫真正的总" tabindex="-1">什么叫真正的总？ <a class="header-anchor" href="#什么叫真正的总" aria-label="Permalink to &quot;什么叫真正的总？&quot;">​</a></h3><p><strong>总 = 如果你的听众只能记住一句话，你希望他记住什么？</strong></p><p>不是标题。不是目录。是你整个汇报的核心论点。</p><p>举个例子：</p><table tabindex="0"><thead><tr><th>不是这样</th><th>而是这样</th></tr></thead><tbody><tr><td>&quot;我今天汇报一下 Q3 项目进展&quot;</td><td>&quot;Q3 我们在核心指标上超预期 20%，但技术债已经影响到交付速度，建议 Q4 投入 30% 资源做偿还&quot;</td></tr><tr><td>&quot;关于下一代手术机器人架构的思考&quot;</td><td>&quot;当前架构在远程场景下的延迟不可接受，建议将控制链路从集中式改为边缘-中心协同，预计延迟从 200ms 降到 50ms 以内&quot;</td></tr></tbody></table><p>第一个是话题，第二个是观点。<strong>汇报是要给观点，不是给话题。</strong></p><h3 id="检验方法-电梯测试" tabindex="-1">检验方法：电梯测试 <a class="header-anchor" href="#检验方法-电梯测试" aria-label="Permalink to &quot;检验方法：电梯测试&quot;">​</a></h3><p>每次写完 PPT，问自己：如果我在电梯里遇到老板，只有 30 秒介绍这个汇报，我能不能讲清楚三件事？</p><ol><li>什么问题/机会</li><li>我的核心结论</li><li>我需要他做什么决定</li></ol><p>如果你讲不出来，说明你的&quot;总&quot;还没想清楚。回到第一页重新写。</p><h3 id="分-mece-不是一个玄学概念" tabindex="-1">分：MECE 不是一个玄学概念 <a class="header-anchor" href="#分-mece-不是一个玄学概念" aria-label="Permalink to &quot;分：MECE 不是一个玄学概念&quot;">​</a></h3><p>分，就是把你的核心论点拆成支撑它的子论点。拆解的黄金标准是 MECE——<strong>Mutually Exclusive（相互独立）, Collectively Exhaustive（完全穷尽）</strong>。</p><p>说人话：<strong>不重不漏。</strong></p><ul><li>不重：每个子论点之间不要有重叠。如果一个证据同时支撑两个子论点，说明你的分类有问题。</li><li>不漏：所有子论点加起来，要能完整覆盖你的核心论点。不能有逻辑缺口。</li></ul><p>实操方法：写完大纲后，画一个二维矩阵或用最简单的列表检查——能不能一眼看出每个子论点的边界？如果两个子论点边界模糊，合并或重新切分。</p><h3 id="再总-不是重复-是升华" tabindex="-1">再总：不是重复，是升华 <a class="header-anchor" href="#再总-不是重复-是升华" aria-label="Permalink to &quot;再总：不是重复，是升华&quot;">​</a></h3><p>最后的&quot;总&quot;不是把开头的话再说一遍。它要做三件事：</p><ol><li>回顾核心结论（呼应开头）</li><li>点出关键洞察（你在过程中发现了什么）</li><li>明确的行动呼吁（下一步做什么，谁来做，什么时候做完）</li></ol><hr><h2 id="第二条-一页一个信息-不是一页一堆信息" tabindex="-1">第二条：一页一个信息，不是一页一堆信息 <a class="header-anchor" href="#第二条-一页一个信息-不是一页一堆信息" aria-label="Permalink to &quot;第二条：一页一个信息，不是一页一堆信息&quot;">​</a></h2><p>这是最容易被疲劳状态激活的坏习惯。当你累了，你会想&quot;这一页再塞一个图也没关系吧&quot;。</p><p>有关系。<strong>每一页 PPT 只能承载一个核心信息。</strong> 如果你发现自己在某一页上放了三个要点、两张图、一个表格——拆成三页。</p><p>这不是浪费页面。页面是免费的，听众的注意力才是昂贵的。</p><h3 id="自检问题" tabindex="-1">自检问题 <a class="header-anchor" href="#自检问题" aria-label="Permalink to &quot;自检问题&quot;">​</a></h3><p>每做完一页，问自己：</p><ul><li>这一页的 <strong>one message</strong> 是什么？能不能用一句话说出来？</li><li>如果删掉这一页，整个汇报的逻辑链条会断吗？（如果不会，这一页可以删）</li><li>听众看完这一页，目光应该落在哪里？（如果没有明确的视觉焦点，你的排版有问题）</li></ul><h3 id="标题即结论" tabindex="-1">标题即结论 <a class="header-anchor" href="#标题即结论" aria-label="Permalink to &quot;标题即结论&quot;">​</a></h3><p>不要把标题写成&quot;Q3 营收分析&quot;。把标题写成&quot;Q3 营收同比增长 15%，核心驱动力是海外市场&quot;。</p><p><strong>标题应该是一个完整的陈述句，包含结论。</strong> 这样即使听众走神了，只看标题也知道这一页在说什么。</p><hr><h2 id="第三条-先搭骨架-再填肉" tabindex="-1">第三条：先搭骨架，再填肉 <a class="header-anchor" href="#第三条-先搭骨架-再填肉" aria-label="Permalink to &quot;第三条：先搭骨架，再填肉&quot;">​</a></h2><p>很多人打开 PPT 的第一件事是——做封面。或者更糟，开始调字体。</p><p>这是错的。<strong>在打开 PowerPoint 之前，你应该已经完成整个汇报的逻辑结构。</strong></p><h3 id="推荐流程" tabindex="-1">推荐流程 <a class="header-anchor" href="#推荐流程" aria-label="Permalink to &quot;推荐流程&quot;">​</a></h3><ol><li><strong>白纸/A4 笔记本/纯文本编辑器</strong>：写出你的核心论点（总）</li><li><strong>列出支撑论点的 3-5 个子论点</strong>：这就是你的章节结构</li><li><strong>为每个子论点列出关键证据</strong>：数据、案例、图表、引用</li><li><strong>检查逻辑链</strong>：从子论点→核心论点的推理是否成立？有没有跳跃？</li><li><strong>画出故事线</strong>：把这些章节串成一个叙事——不仅仅是在罗列信息，而是在引导听众完成一次认知转变</li><li><strong>最后才打开 PPT</strong>：这时候你只是在做翻译工作，把已经想清楚的东西视觉化</li></ol><blockquote><p>在纸上想不清楚的东西，在 PPT 里也讲不清楚。</p></blockquote><hr><h2 id="第四条-讲一个故事-而不是报一份清单" tabindex="-1">第四条：讲一个故事，而不是报一份清单 <a class="header-anchor" href="#第四条-讲一个故事-而不是报一份清单" aria-label="Permalink to &quot;第四条：讲一个故事，而不是报一份清单&quot;">​</a></h2><p>最糟糕的 PPT 不是做得丑的 PPT，是<strong>让人不想往下翻的 PPT</strong>。</p><p>让人想往下翻的关键是：<strong>制造认知缺口，然后填补它。</strong></p><h3 id="三种最常用的叙事结构" tabindex="-1">三种最常用的叙事结构 <a class="header-anchor" href="#三种最常用的叙事结构" aria-label="Permalink to &quot;三种最常用的叙事结构&quot;">​</a></h3><p><strong>结构一：问题 → 分析 → 方案 → 验证</strong></p><p>最经典，适合方案汇报、技术评审。</p><ul><li>问题：现状有什么痛点？（让听众产生&quot;确实需要解决&quot;的共鸣）</li><li>分析：根因是什么？我们尝试过什么？（展示思考深度）</li><li>方案：我建议怎么做？（核心价值输出）</li><li>验证：为什么这个方案可行？（数据、案例、推演）</li></ul><p><strong>结构二：现状 → 目标 → 路径 → 风险</strong></p><p>适合战略规划、年度计划。</p><ul><li>现状：我们在哪里？</li><li>目标：我们要去哪里？多快到达？</li><li>路径：分几步走？每一步的里程碑是什么？</li><li>风险：最大的不确定性是什么？我们的应对策略是什么？</li></ul><p><strong>结构三：观点 → 论证 → 反驳 → 结论</strong></p><p>适合需要说服的场合，比如争取资源、推动决策。</p><ul><li>观点：直接亮出核心主张</li><li>论证：三层递进式支撑（数据、逻辑、案例）</li><li>反驳：主动回应最可能的质疑（展示你思考过反面）</li><li>结论：重申主张 + 行动请求</li></ul><h3 id="每个章节内部的微观节奏" tabindex="-1">每个章节内部的微观节奏 <a class="header-anchor" href="#每个章节内部的微观节奏" aria-label="Permalink to &quot;每个章节内部的微观节奏&quot;">​</a></h3><p>即使在一个章节内部，也要保持<strong>铺垫→展开→小结</strong>的节奏：</p><ul><li>铺垫（1 页）：这一章要回答什么问题</li><li>展开（3-5 页）：用数据和分析回答问题</li><li>小结（1 页）：这一章的核心结论，以及它如何衔接到下一章</li></ul><hr><h2 id="第五条-尊重听众的认知负荷" tabindex="-1">第五条：尊重听众的认知负荷 <a class="header-anchor" href="#第五条-尊重听众的认知负荷" aria-label="Permalink to &quot;第五条：尊重听众的认知负荷&quot;">​</a></h2><p>汇报和其他写作形式有一个根本区别：<strong>听众不能回看，不能暂停，不能调速度。</strong> 他们是完全被动的信息接收者。</p><p>这意味着你的 PPT 必须在认知负荷管理上做到极致。</p><h3 id="具体规则" tabindex="-1">具体规则 <a class="header-anchor" href="#具体规则" aria-label="Permalink to &quot;具体规则&quot;">​</a></h3><p><strong>7±2 法则的现代理解</strong>：一页上的信息块不要超过 5 个。信息块包括：标题、图表、bullet point 组、图片、注释。超过 5 个，听众的注意力就会分散。</p><p><strong>三秒原则</strong>：听众扫一眼你的页面，三秒内应该能判断出这一页在讲什么。不是读完，是判断。如果三秒判断不了，你的视觉层次有问题。</p><p><strong>少即是多</strong>：</p><ul><li>文字：能删就删，保留核心陈述</li><li>数字：不要给原始数据表，给趋势和对比</li><li>图表：一张图讲一件事，不要在一张图里塞三条信息</li><li>动画：能不用的地方不用，动画是有成本的注意力索取</li></ul><p><strong>用对比代替罗列</strong>：与其说&quot;A 方案成本 50 万，B 方案成本 30 万&quot;，不如说&quot;B 方案比 A 方案省 40% 成本&quot;。人脑对对比的感知远强于对绝对值的记忆。</p><hr><h2 id="第六条-图表不是装饰-是论证工具" tabindex="-1">第六条：图表不是装饰，是论证工具 <a class="header-anchor" href="#第六条-图表不是装饰-是论证工具" aria-label="Permalink to &quot;第六条：图表不是装饰，是论证工具&quot;">​</a></h2><p>疲劳时最容易做的一件事：找到一个看着还行的图，贴上去，然后不再想它。</p><p>每张图放上去之前，问三个问题：</p><ol><li>这张图在支撑什么论点？</li><li>如果删掉这张图，这个论点还成立吗？</li><li>听众能自己读懂这张图吗？（坐标轴标签、图例、单位都清楚吗？）</li></ol><p>如果问题 2 的答案是&quot;成立&quot;，这张图就是装饰，可以删。如果问题 3 的答案是&quot;不能&quot;，你需要重新做这张图。</p><h3 id="图表标题规则" tabindex="-1">图表标题规则 <a class="header-anchor" href="#图表标题规则" aria-label="Permalink to &quot;图表标题规则&quot;">​</a></h3><p>和页面标题一样：图表的标题应该陈述结论，而不是描述内容。</p><table tabindex="0"><thead><tr><th>不要</th><th>要</th></tr></thead><tbody><tr><td>&quot;各季度营收对比&quot;</td><td>&quot;Q3 海外营收首次超过国内，占比 52%&quot;</td></tr><tr><td>&quot;延迟测试结果&quot;</td><td>&quot;边缘-中心协同方案延迟降至 48ms，满足临床需求&quot;</td></tr><tr><td>&quot;用户满意度调查&quot;</td><td>&quot;净推荐值从 32 升至 47，&#39;响应速度&#39;改善最明显&quot;</td></tr></tbody></table><hr><h2 id="第七条-准备-slides-之外的东西" tabindex="-1">第七条：准备 slides 之外的东西 <a class="header-anchor" href="#第七条-准备-slides-之外的东西" aria-label="Permalink to &quot;第七条：准备 slides 之外的东西&quot;">​</a></h2><h3 id="过渡句" tabindex="-1">过渡句 <a class="header-anchor" href="#过渡句" aria-label="Permalink to &quot;过渡句&quot;">​</a></h3><p>每一页翻到下一页的时候，不要沉默。提前准备好过渡句，让章节之间的衔接自然流畅。</p><p>例如：</p><ul><li>&quot;刚才讲的是问题本身，接下来说我们尝试过的解决方案。&quot;</li><li>&quot;数据层面我们看到了趋势，但更关键的是这组数据背后的原因。&quot;</li><li>&quot;前面三个方案各有优劣，我的建议是选 B，原因有三点。&quot;</li></ul><h3 id="备用-slides-appendix" tabindex="-1">备用 slides（Appendix） <a class="header-anchor" href="#备用-slides-appendix" aria-label="Permalink to &quot;备用 slides（Appendix）&quot;">​</a></h3><p>把详细数据、技术细节、补充材料放到附录里。被问到的时候你能翻出来，但主讲时不占用时间。这让你既专业又不啰嗦。</p><h3 id="预判问题" tabindex="-1">预判问题 <a class="header-anchor" href="#预判问题" aria-label="Permalink to &quot;预判问题&quot;">​</a></h3><p>正式讲之前，列出听众最可能问的 5 个问题，准备好答案。如果这些问题能在正文中前置回应，更好——直接消灭疑问比被问到再解释更有说服力。</p><hr><h2 id="写到快崩溃时的自救清单" tabindex="-1">写到快崩溃时的自救清单 <a class="header-anchor" href="#写到快崩溃时的自救清单" aria-label="Permalink to &quot;写到快崩溃时的自救清单&quot;">​</a></h2><p>当你盯着 PPT 觉得脑子一片空白、想砸电脑的时候，按这个顺序过一遍：</p><ol><li><strong>站起来离开屏幕 5 分钟。</strong> 泡杯茶，走一圈。大脑需要从细节模式切回全局模式。</li><li><strong>回来只看第一页。</strong> 你的核心论点还成立吗？如果连你自己都说服不了，后面写得再漂亮也没用。</li><li><strong>大声讲一遍你的逻辑线。</strong> 不用看 PPT，就用手比划——先讲什么，再讲什么，最后讲什么。如果能讲顺，说明逻辑没问题，只是卡在表达上。如果讲不顺，问题在逻辑，回到大纲重排。</li><li><strong>找一页你做得最满意的，对照检查其他页。</strong> 这能帮你快速识别哪些页是&quot;糊弄过去&quot;的。</li><li><strong>接受&quot;完成比完美重要&quot;。</strong> 汇报的 deadline 不会等你。在有限时间内，逻辑完整 &gt; 视觉精美 &gt; 细节丰富。先保证逻辑不断，再考虑美化的程度。</li><li><strong>给自己设一个硬停时间。</strong> 不能在 PPT 上无限耗下去。定一个时间点（比如讲之前 2 小时），到点就停，不再改内容，只改明显的错误。</li></ol><hr><h2 id="最后-ppt-不是目的-决策才是" tabindex="-1">最后：PPT 不是目的，决策才是 <a class="header-anchor" href="#最后-ppt-不是目的-决策才是" aria-label="Permalink to &quot;最后：PPT 不是目的，决策才是&quot;">​</a></h2><p>写 PPT 最容易迷失的一点是：把&quot;做好 PPT&quot;当成目标本身。</p><p>PPT 只是一个工具，它的目的是<strong>帮助听众做出你期望的决策</strong>。如果你讲完之后，听众说&quot;PPT 做得真好&quot;，但什么决定都没做——你的 PPT 是失败的。</p><p>所以在每一次开始写之前，先写下来：</p><blockquote><p><strong>我希望听众在听完这个汇报之后，做出的具体行动是什么？</strong></p></blockquote><p>把这句话贴在显示器上。每写一页，问自己：这一页在推动听众走向那个行动吗？</p><hr><blockquote><p>💡 <strong>核心原则：</strong> 总分总结构是骨架，故事线是血脉，认知负荷管理是边界。累的时候退回到这三个东西——你的总论点是什么、你的故事线通不通、每一页对听众来说重不重。其他的都是锦上添花。</p></blockquote><hr><p><em>这篇是写给自己的。下次写 PPT 写到烦躁的时候，回来读一遍。如果觉得某一条特别有用但没做到，就把它贴在屏幕边上。</em></p>',110)])])}const P=a(i,[["render",e]]);export{q as __pageData,P as default};
